INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('rec2Zs711uINQ7iDu', 'habitart-espai-creatiu-bravafang-girona', 'Hàbitart espai creatiu - bravafang ', 'Av mediterránea 344 local 2 17256 platja pals ', '680 593 553', 'morenomoncada@yahoo.es', '', 'Pals', 'Hàbitart - Brava Fang és un espai creatiu i artesanal ubicat a Pals (Costa Brava). Ofereix tallers de ceràmica, cosmètica natural, espelmes aromàtiques, macramé i manualitats per a totes les edats. És un projecte que neix del desig de crear amb les mans, compartir experiències i reconnectar amb allò essencial. S''organitzen: 
- Tallers regulars i experiències puntuals 
- Activitats a mida per a grups, turisme, escoles o celebracions 
- Projectes creatius en contacte amb la terra i l''entorn natural 

Hàbitart vol oferir un hàbitat creatiu, un refugi artístic. On l''art, les mans i la imaginació es trobin.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/kgbB7hGLILmLBfw_MaIzCQ/BPaJQ5sneFgwsi8g-t_Q50UQ0rmlACM8I44Pdm_h_VK505dYqgoUFMUO99yrLpoxkSY7QFsJapbpRGxVBfYx4nCEc6QTgCheQfPKjn544t8ArFjBAwZzKY2jKIvjtAyySuQWfcIh87fHAsJNALSvbQ/KKE_3zhpjNJyNDTMPukwB1K6P2LjK7cAXsiq2NGKtaQ', TRUE, '', 'girona')
