VALUES ('recI3qPJFGpuL4MFX', 'instep-girona', 'INSTEP', 'C/ Caterina Albert', '650 47 51 24', '', '', 'Bescanó', '', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/961-Y79zbILKmFfZQsMKIg/Yy26YN0744o7sdBxRgUmyA3ZFgPPyxAH_VHJcIKM4o5QF3bEKHkMFt5GoWC0xm9aPCh0c22aQwm_wnMpnhBsEtx-HcCI5xRkBj9q4tNYBtz9jNhPVLSXYClRusQ6gMTxqCitDRSzwruJOdHOOFDgFw/3b4xWGT7zODIMWEl5clm-sM9sxJjJH8T_smTEHn4I8Q', TRUE, '', 'girona')
