INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recML7usx4l8Ev7GW', 'autoocupacio-girona', 'AUTOOCUPACIO', 'Parc Científic i Tecnològic de la UdG, C/Emili Grahit,91 Edifici Narcís Monturiol Girona 17003', '972 41 01 50', 'info@autoocupacio.org', 'https://www.autoocupacio.org/', 'Girona - Montilivi-Palau', 'La Fundació Autoocupació és una entitat privada sense ànim de lucre que, des de fa gairebé 40 anys, acompanya les persones perquè puguin desenvolupar el seu projecte professional, ja sigui creant una empresa, millorant la seva ocupabilitat o impulsant la seva carrera laboral. La nostra missió és ajudar les persones a convertir les seves idees i vocacions en oportunitats reals, oferint un acompanyament integral i personalitzat en totes les etapes del seu desenvolupament professional.

A la delegació de Girona oferim serveis d''assessorament a persones emprenedores, suport en la creació i consolidació d''empreses, programes de mentoring empresarial, orientació professional i formació especialitzada. També desenvolupem projectes innovadors com la Llançadora d''Autoocupació, que combina formació, acompanyament individualitzat i experiència pràctica per ajudar les persones participants a transformar una idea de negoci en un projecte empresarial viable. 

El nostre model de treball es basa en l''atenció personalitzada, la innovació, la igualtat d''oportunitats i la col·laboració amb empreses, administracions i entitats del territori. Acompanyem tant persones que volen emprendre com professionals que busquen nous reptes laborals, contribuint al desenvolupament econòmic i social del territori mitjançant la promoció de l''emprenedoria, l''ocupació i el talent.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/YO4B-e1rSiOntHT9Uja7OQ/u11nD3u_RNZu-ctSFD7JyZDwZQEBrr-l67hLMNMw2ArZ3MvtYTgoc9aWh_OJ1KcSQ_aCtd5xt0H3T8Mn9AEZJiPNEF5Esjp9F6Q5Q_seJxK9_9H2mJW8I-8yI84Q7mt3cYsirAglN8gFYLodRSh-tA/LPzOQta_VYjLQV7baXNoXdKwEU44g5fOteisgDqmzSc', TRUE, '10/08/2026-23/08/2026
25/12/2026-07/01/2027
', 'girona')
