INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recN6Rze1OGCVUile', 'mirades-sils-girona', 'MIRADES', 'Masia Can Serra, Veïnat de la Barceloneta, 15', '676313185', 'info@miradessils.com', 'https://miradessils.com/', 'Sils', 'Mirades és un projecte d’educació lliure i viva ubicat a la Masia Can Serra del Veïnat de la Barceloneta de Sils (La Selva, Girona). Oferim un espai d’acompanyament diari per a famílies, amb infants de 9 mesos (aprox.) fins als 6 anys, que busquen una alternativa a l’escola convencional, on el respecte pels ritmes de l’infant i el contacte directe amb la natura són els pilars fonamentals.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/RSSMiWpr0TizQT3OX_tcfQ/LEXIdKLUM2BJoaxonwS4TiQxHFReZnpDc9zGZx76Ak_UUPxVziKLGiRSW5sMMmovO6uoAuizawZmHOVgs3QmWm1mOy2Lpzl3SZDM-u2K5yUAeFhap0oLwmIQLgCSsi0Tfw3PKvsPKnfifbOVGNLxl3YUQyWewuVw4DeRpNf9Wp1hbovcVz_zRfonENGxGpN4UvH7pvMYHxOsstNC3e8N4w/kyR5CYGd1nSDDNZn-bsorTpCU6wwktW_7Pzwyt0_dyE', TRUE, '', 'girona')
