INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recT618bKVEBAVmpP', 'fundacio-torremirona-esport-i-salut-girona', 'Fundació Torremirona - Esport i Salut', 'N-260, Km 47, 17744 Navata, Girona', '972 56 54 29', 'info@fundaciotorremirona.com', 'https://www.clubtorremirona.com', 'Navata', 'La Fundació TorreMirona - Esport i Salut té com a objectiu principal la promoció i la pràctica de l''esport com a mitjà per a la millora de la qualitat de vida de les persones. Treballem per fomentar el desenvolupament personal i social a través de l''esforç, el respecte, el compromís i la solidaritat, contribuint així a crear una societat més sana, activa i solidària.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/wUpSRHaO5ZeijbUrpDIGww/5IskC4UEEQuHhkAH5Bc9vidpcVjUfisazuYfYoGpDichuLyVAzg92pdzx6_9LcuAKTPPg1bdjuNNNQjCERYQbYV7M_pDYUAlXc2DW0pv8mGuYXihKOSEUmeqyuUhqmtu3AGGjA9ApnlVc20GA_09QQ/xpTdley8gq0t8yUxkTzhiam2ILVZBKQSKB3XYQbV1sw', TRUE, '', 'girona')
