INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recTJoSgWJkav7Fw0', 'mediterrania-escola-de-dansa-irlandesa-girona', 'Mediterrania Escola de dansa Irlandesa', ' C/ Sunyer 46. 17003. GIRONA', '637 579 754', 'info@mediterraniaescola.cat', 'https://mediterraniaescola.cat/', 'Girona - Domeny i Fontajau', 'L’Escola és un somni fet realitat gràcies al compromís, la recerca i la perseverança de professors, ballarins i famílies. Una obertura a nous coneixements, que t’endinsarà en un viatge transformador per explorar més aspectes de tu mateix@. Compromesos amb l’educació, continuem formant-nos en la tradició per innovar. Garantim una formació cuidada i professional on les persones, la música i els nous projectes que es proposen ens permeten oferir la màxima qualitat.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/-dQj68j1iYtdu5fcVWfd6Q/poToeZ9gWsSn0Aub5jWtrCT_srbhX9wcQgonBCcmoJTRLytrh2Y4MVgzAGg3TL2YdJsurDwITF5Lmi6mphxIL18GBqJd77UxyhA15FKsZ156NjIb_MY0C_KzC8gkwCu_A2WUSaGYRNor6jMs6W0iyw/M3uBQZcbu2Yo0MzqocJiG_skiCQfU2w-vmocpjSilO0', TRUE, '', 'girona')
