INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recULd44Ln90T6rsz', 'centre-civic-santa-eugenia-girona', 'Centre Cívic Santa Eugènia', 'C. Santa Eugènia, 146', '972 245 111', 'ccsantaeugenia@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Santa Eugènia', 'El Centre Cívic Santa Eugènia està situat en una antiga masia del segle XV, coneguda com Can Ninetes. És un centre cívic que presenta una àmplia i diversa programació cultural, on les entitats de la zona tenen una important participació. Destaquen les nits literàries, els espectacles, les exposicions i les tertúlies i debats. El conjunt de cursos de plàstica, cuina, ball, ioga, etc., són també un bon referent per a molts de ciutadans i ciutadanes del barri i de la ciutat.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/B0lygzCXceMqKcGREQZ_Dw/tOmid1Z8sDcI4AGY_QkS0XRdbM0gMyEuuLuokok7uLgeHnBgOQwOtnr8CzdvEWgCnBNWBvXsYwjJlruobjMGKaRdKVwWfs2lNTTYUzNupJdZHp_2J0vJVCv310Cqjvk-VXAPVQFBGNuZxGMyC9wrZMKsWKUMiZqKBTRD9joWXNM/YppJlHfM4JjToXvuIEOPDRCcmM9n7vpjAw5RhSspQ-I', FALSE, '', 'girona')
