INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recW2bp4m8lOnAUai', 'centre-civic-pont-major-girona', 'Centre Cívic Pont Major', 'C. Pont Major, 67-73', '972 205 244', 'ccpontmajor@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Pont Major', 'El Centre Cívic Pont Major (2003) és un equipament municipal adreçat al conjunt de la població, a les associacions del barri i col·lectius diversos. El centre ofereix una programació que s''organitza a través de la participació activa de les entitats i col·lectius del barri. Activitats per a gent gran promogudes per l''Associació de Jubilats La Unió, projectes i cursos dinamitzats pel Col·lectiu de dones La Cata i festivitats populars promogudes per l''associació de veïns i altres associacions de la zona, pretenen ser un clar exemple de dinamització social i cultural del sector.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/B0lygzCXceMqKcGREQZ_Dw/tOmid1Z8sDcI4AGY_QkS0XRdbM0gMyEuuLuokok7uLgeHnBgOQwOtnr8CzdvEWgCnBNWBvXsYwjJlruobjMGKaRdKVwWfs2lNTTYUzNupJdZHp_2J0vJVCv310Cqjvk-VXAPVQFBGNuZxGMyC9wrZMKsWKUMiZqKBTRD9joWXNM/YppJlHfM4JjToXvuIEOPDRCcmM9n7vpjAw5RhSspQ-I', FALSE, '', 'girona')
