INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recY1lKxx9NKIypox', 'la-diana-girona', 'La Diana - Escola de Teatre i Teatre Musical', 'Passeig d''Olot, 68', '644 251 800', 'hola@ladiana.cat', 'https://ladiana.cat/', 'Girona - Santa Eugènia', 'La Diana és una escola d’arts escèniques inspirada en el mètode Stanislavski, que utilitzen altres centres com Actor’s Studio de Nova York.

Amb el nostre mètode, cada alumne farà un treball d’investigació basat en l’assaig, l’autocrítica i en l’avaluació continuada de cada exercici per trobar les eines necessàries per ser actors i actrius professionals, espontanis, creatius, participatius i constructius.

Volem aconseguir que l’alumne experimenti les emocions reals que viu el personatge jugant a creure i viure les situacions de l''”aquí i ara” de l’escena.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/QNVvNvzZNComlNlYRwxE_g/qdnKOpTrukEINqO1ISW1jB7fiTlsOvFoVHLFr109S91c3ZYd9L18UXtfEjnvIS3d5a46zi9T0cL-RBJuH3Q8o_-jnia4hAQH2TU-fqiz-_dvWre0OodcEUMnjnIHt_yOaTnYXn6uOvoPMGQ1HCF8_KQ4si3wwns141uB_2LOl0FBZxsgJxqUFujeR6I0NndbQn53IsbyPMx0An6rf7CxeA/2dX1s1KIMJidpaV93p3ITFu36CR8SpU_8OcDOJxMaeA', TRUE, '', 'girona')
