INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recZDZsJn1FCIrjGj', 'art-i-teca-girona', 'Art i Teca', 'C/ Nou, 46', '972685755', 'artiteca.emporda@gmail.com', 'https://www.artiteca.com', 'Figueres', 'Al cor de l''Empordà, neix una col·laboració única entre petits artistes i productors artesans que comparteixen una passió per l''autenticitat i la qualitat.

Units sota el sostre acollidor del nostre local a peu de carrer, aquests creadors exhibeixen els seus tresors d''Art i Teca.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/bpFFuLH_pBNE0ri--bp6ow/DDjoHyH2SqNrqfh7Rs0bVyDl9VMiBzGXMOuUoYRP3YDCC-jPGTxbiJLRAR5Z99qL_uxEpiGLxxuWR8x2iC6nfRcVt0b-vHUSqa-M1wSmqSEMUeaLp7SAl99sq37EL3B9zb_TKZ8vxl8llnJ7WdBoYw/_OBiKYSv5kHcMp0WPaJaEi1wNN2TLmveHzivGT8SAWU', TRUE, '', 'girona')
