INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recmJ4g1SaTJycGUy', 'centre-civic-sant-narcis-girona', 'Centre Cívic Sant Narcís', 'Plaça Assumpció, 26-27', '972 237 063', 'ccsantnarcis@ajgirona.cat', 'www.girona.cat/ccivics', 'Girona - Sant Narcís', 'El Centre Cívic Sant Narcís (1989) és un equipament municipal plenament consolidat al barri de Sant Narcís i amb una projecció destacada cap a la resta de la ciutat gràcies a la seva localització, las diversitat d''espais de què disposa i una programació extensa i variada, promoguda cada vegada més a partir de la iniciativa social i cultural. Hi trobem molta participació en els casals (casals, esplais, jocs organitzats...), seguit de les grans activitats organitzades bàsicament per col·lectius i associacions del barri.

', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/B0lygzCXceMqKcGREQZ_Dw/tOmid1Z8sDcI4AGY_QkS0XRdbM0gMyEuuLuokok7uLgeHnBgOQwOtnr8CzdvEWgCnBNWBvXsYwjJlruobjMGKaRdKVwWfs2lNTTYUzNupJdZHp_2J0vJVCv310Cqjvk-VXAPVQFBGNuZxGMyC9wrZMKsWKUMiZqKBTRD9joWXNM/YppJlHfM4JjToXvuIEOPDRCcmM9n7vpjAw5RhSspQ-I', FALSE, '', 'girona')
