INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recpRXfT2sGwy7dHT', 'espai-meraki-girona', 'Espai Meraki', 'C/ Puig Sureda, 69', '621 29 60 40', 'espaimerakiescala@gmail.com', 'https://espaimerakiescala.wixsite.com', 'l''Escala', 'Espai de joc, descoberta i acompanyament per a infants de 0 a 4 anys, amb grups reduïts i una proposta basada en el joc lliure, activitats sensorials, psicomotricitat, música, creativitat i experimentació, sempre respectant els ritmes de cada infant. Oferim servei de canguratge per hores, dies puntuals i estades setmanals o mensuals en un entorn familiar i acollidor.

També organitzem tallers puntuals dirigits a infants i les seves famílies, amb propostes lúdiques, creatives i vivencials que fomenten el vincle familiar. A més, comptem amb serveis professionals d''acompanyament emocional i psicològic, especialment en l''àmbit perinatal, criança i família, així com altres activitats i serveis orientats al benestar emocional, el desenvolupament infantil i el suport a les famílies.', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/-5RiQbRGQXMime66EBQlLg/9pk5ELe_c6-x2INt_e-xLyPZqTTSos4y3qj5FhLsDc_n1JiuGmRm-IAaS64AVeXaaJlxuaPVgtWAe_nqqdGylCt2XQPfZUhrVBs3aE6dkc9Y8bCz0A4vlUIeDBpW5xticv0jFCHd0NKWkA21sgdmOg/kx-rYQaZNQpPICUt0BYs6FbxAQKSvzlimTIxmdXz9a8', TRUE, '', 'girona')
