INSERT INTO public.centres (id, slug, nom, adreca, telefon, email, web, barri, descripcio, imatge_url, interessat, vacances, ciutat)
VALUES ('recsBRHdv4X6Q3V3T', 'la-moderna-girona', 'La Moderna', 'Plaça dels Jurats 1, Girona', '682 483 088', 'emmg@emmg.info', 'https://www.emmg.info/', 'Girona - Barri Vell', 'Facilitem l’accés a la pràctica musical a totes les edats, acompanyant-ne els interessos formatius i expressius.

Estem compromesos amb la qualitat educativa i entenem l’art com un àmbit de socialització i de gaudi al servei de les persones, col·lectius i agents culturals.

Liderem l’ensenyament de les músiques actuals a les comarques gironines, on hem esdevingut una institució clau per l’abast de les activitats socioeducatives que duem a terme.

Actualitzem permanentment la nostra oferta formativa i estem activament vinculats amb la vida cultural i social de la ciutat i de les comarques gironines.

', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/c8Jt3Ta7QNFH82awRdWJsg/6YedT3bczbHwZHKendYWMqQjkpWdUlGJXoen8uhIxWzVXPuyEfJSrT7kHp-9OWpe3K21QnisOKBtzHouGbsfDkAnCxc4iiNAu2mlYsLsRg7sgOERD1Vg69W8VO_lYu7Kv9os4sBQp8Z8ip91tz69Z6BYGi9iHY9lU0OK3yMwCiU/cBiDNd-YWWKhVT_tbrf0lLJA0eDqKxEbiAGD4xdjnck', FALSE, '', 'girona')
