VALUES ('rec6CMbNGn8o4m6zp', 'extraescolar-dansa-contemporania-2-11-12-la-central-girona-vista-alegre-carme-girona', 'Dansa Contemporania 2', 'La Central', 'recKdVzY8nxvbba5N', 'Girona - Vista Alegre - Carme', 'Dansa', '"Dansa"', '11-12', '45', FALSE, FALSE, FALSE, '17''30h a 18''30h', 'Dimecres', 'Dansa contemporania per a joves. Tecnica de moviment modern i expressio artistica. Participants en coreografies i espectacles.', '1h15min', 'Grups reduits', '', 'Octubre', 'Catala', '', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
