VALUES ('recGtQD4PLECpK0zp', 'extraescolar-angles-per-nens-i-nenes-de-8-a-10-anys-eica-girona-eixample-girona', 'Anglès per nens i nenes', 'Eica', 'recHgLj4ryjLawaNz', 'Girona - Eixample', 'Idiomes', '"Idiomes"', 'De 8 a 10 anys', '88', FALSE, FALSE, FALSE, 'De 16:00h a 17:30h o de 17:30h a 19:00h', 'De dilluns a divendres', 'Maximitza els seus dots de comunicació de la forma més efectiva a la nostra escola de Girona. Els nostres cursos d’anglès per nens a partir de 8 anys els brinden una base sòlida de l’idioma per sempre.', '1:30 h', '', '', '', 'Anglès', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/KJ9XIKyvXWLBZJx97D5jOQ/WxyDGQuwGUJ7vtH_5LFNCxx3x6gv4krflxBSHX5TUzcgN7fmB-8qWfD2GXMny3RXXUAyvqiVlweUoK4KFeGY4WRUR-ZRdlB6_Lz4Mj_bihIa9uKVJIA0211TxAwR3cNEZ3z3gMDBMeX9sklhchqU7LNSUslui5GMdmIs8TOnTL9_jiBJrWBGyi5TuXQHGKYD/4xh0u17t9IVzeA6e_fjpbVawsCgPErHRm22yGcTCgQk', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/yUV7Gs65C7UzOhVoyk7C5Q/JRgBsi6a_kZ3dl9WFClJ3eftHQbi8e8sZq-PPabqRRBJqHuW9HhUp8w_7qBA6V8XhPpQtpzJW62UKwu5kZpuA03eqaDc4uV_WdcIziaL0I1Q1Yvvnk5eWj8kYuf0aGPAbGlxHIOA1EJSUwrdPWL7WQ/qO_H68R8pqXcNOplxShbw5CfEjrskRG6W1CSRg3GD6g', '{}', 'Anglès', 'Extraescolar', '', '', '', '', 'girona')
