VALUES ('recV8Qvnn69t2r62q', 'extraescolar-frances-en-grup-16-18-anys-eis-girona-girona-sant-narcis-girona', 'Francès en grup', 'EIS Girona', 'recpX9F9ctmF2Y4tN', 'Girona - Sant Narcís', 'Idiomes', '"Idiomes"', '16-18 anys', '87', FALSE, FALSE, FALSE, '19:00 – 21:00h', 'De dilluns a dijous', 'Aquest curs t’ajudarà a comunicar-te de manera fluida i segura en francès. L’objectiu principal és que puguis expressar-te amb naturalitat en situacions quotidianes i professionals.', '2h', '', '', '', '', '', TRUE, 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/PPQlxNQioUPOtjynA_sF3g/__MdT6b7ia32JUd6zGxBjqSjF8E7GTN6C5_1OlrSa2RCat5w9_ePCjWJc8mST2wkD9DWnuGjv0k56lNvrPFDLaXX7-CCYJnaWWia5zO5GiEKbs9pY5yhlnPOEcUNmumHUBnbX1MLo-pSmiauUqkhoIZ-YH6AosL2FnT9nD0T14o/-PM9Rye13UXgJHjGGWSNpH7x5XsVeh4SXzVbWL-ssGA', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/Uram-99oc1AXDARVUEGZqA/cpEPhlEyAbU6xq5mZzk5ysDZGtIoIQx4GeomE0qF4EXYg7RVdjPBO6m7CMICYKjRrGtNj5WH6zH2jVEpuwrvncbDRRwTibmBDBddJKLha_DoplCa3pgb2Wm93VVZPqhbscEojL3FuAV4zr4t5-0zTA/WzVvXelP0W_-TIXkLkggNXcGOCCRhSp6cQNcX1bCf0w', '{}', 'Francès', 'Extraescolar', '', '', '', '', 'girona')
