VALUES ('recVqwnaq1K1RxcxG', 'extraescolar-guitarra-baix-a-partir-de-6-anys-escola-de-musica-sant-gregori-sant-gregori-girona', 'Guitarra / Baix', 'Escola de Música Sant Gregori', 'rec8bSYPwdb4jZCLe', 'Girona - Domeny i Fontajau', 'Música', '"Música"', 'A partir de 6 anys', '30''→60€ | 40''→80€ | 50''→100€ | 60''→120€', FALSE, TRUE, FALSE, 'A consultar', 'Dimarts i dimecres', 'Pedagogia activa basada en la participació activa, l''expressió vocal, el moviment corporal i la improvisació, amb l''objectiu de desenvolupar l''oïda, la veu, el sentit rítmic... fent que tots els alumnes gaudeixin i creixin gràcies a la música', '', '', '', '', '', 'Marcel Torres', TRUE, 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/PogyZKUY5F-pyg6x3hwvew/8RYwtJX0vpi16wBMUXFA3cAB_CqULrDcwhjHF4WmtEDrQ2CKtqZvfaa_DBvm6iz8fjD6L-OEheZQYbEhGhE30CC1HXV8adq0EEoJlc4DvX3W8MekOxCgTR0W--3cYSpmnSWt1sKY87Xrl4jystQlig/zk23hEgLd-3yvu4wmumu4A6O-kzCdBieZK80XsKlDhc', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/wnpfuFe7Je8ZatH3xqbUsw/v4-RTBhA0sumPSp4fbL2n-6F1S-Men7px2mUCew5PBjzodL0CuZs239PwMiVnqdqphvYiGX0LcLwJMomusmUyIGkaAww_XSQLkgPCIb4EeTe50FElVjwt3d8LusJL5VfEHNWGZkxOHpD4-ZU9NZhCA/ir0yJLSZpzbd9yIobqXKLtOemns4G_WCGffkYPbfK4k', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
