VALUES ('recXyH8jgFDuYthdF', 'extraescolar-teatre-juvenil-galls-15-18-anys-el-galliner-girona-santa-eugenia-girona', 'Teatre juvenil: Galls', 'El Galliner', 'recocKPYDHMx8CNcG', 'Girona - Santa Eugènia', 'Teatre', '"Teatre"', '15-18 anys', 'Des de 45€', FALSE, TRUE, FALSE, 'A triar entre:
