VALUES ('recehY2sm1UhMAvcK', 'extraescolar-patinatge-xou-6-11-anys-cpa-girona-girona-montilivi-palau-girona', 'Patinatge - Xou', 'CPA Girona', 'rec0ddlZph90jdUUf', 'Girona - Montilivi-Palau', 'Esports', '"Esports"', '6-11 anys', '', FALSE, FALSE, FALSE, '', '', 'Equips de patinatge en la modalitat de xou. Diverses categories: Xou Promoció, Xou Júnior i Xou Gran. El CPA Girona ha guanyat múltiples campionats a nivell autonòmic i espanyol.', '', '', '', '', 'Català', 'CPA Girona', TRUE, '', '', '{}', 'Patinatge', 'Extraescolar', '', '', '', '', 'girona')
