VALUES ('rech1lXA5wcRTKOCV', 'extraescolar-castella-per-a-nens-8-11-up-idiomes-girona-eixample-girona', 'Castellà per a nens ', 'UP! IDIOMES', 'reciIofi7Tshw66I8', 'Girona - Eixample', 'Idiomes', '"Idiomes"', '8 - 11', 'Des de 15€/hora', FALSE, TRUE, FALSE, '16:00 - 17:00', 'Dilluns a dijous', 'Fem servir un mètode actiu, lúdic i basat en la immersió natural, pensat específicament per a una edat on la prioritat és que l''idioma entri a través de l''oïda i el joc', '1 h', 'Grups reduïts', '', '6 de juliol', 'Castellà', 'Professors natius', TRUE, 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/nYqU-KkWbwuFM76D7oBJLg/kExk7i1qaSbydpyecZWo3RQfT4EzLN4EfcypRzXl7F7X_kkVQDgruARHhT9ADO4qZNnnpt2s-bMxnOFOdkFcxAPUIeFMaV6YIfr-ZOEwX_3Sz11aZc6uwSPEAy5tIQDCCyyTAJY241a-rf3YV_J0IQ/wzcclCFmKsBkTQNGSpd50eJLTMiCWegbgK_2hVd6SUQ', 'https://v5.airtableusercontent.com/v3/u/56/56/1785859200000/lPagcxyLGo_nLonOPbpqYQ/tguAs7AiGvLM3LrZngTjrefSmfJWQENkiSy48j6KoNjqVH2k2Bxo2hzfv0Alb1ewoU_6gMPNYujP53O9iHqKaGRtVAGDd-6g-QDeEPq1wEDMmkAtQTjSMxMZxUjWaCiK8zHFxIcBUR31eJ3-IoZZ7A/bJo1XaqF2qzhTr6aBhUW95ToX2yySxGFAFLjs4dJOcg', '{}', 'Castellà', 'Extraescolar', '', '', '', '', 'girona')
