VALUES ('recpgqzkHYlem6ndG', 'extraescolar-macrame-mitja-i-ganxet-de-3-a-17-anys-centre-civic-barri-vell-mercadal-girona-barri-vell-girona', 'Macramé, mitjà i ganxet', 'Centre Cívic Barri Vell-Mercadal', 'recpG0Qts1G9JA9a6', 'Girona - Barri Vell', 'Creativitat i Expressió', '"Creativitat i Expressió"', 'De 3 a 17 anys', '120€/l''any', FALSE, FALSE, FALSE, 'De 17.30 a 19 h', 'Dimarts', 'Aquesta activitat va dirigida a tots els infants i joves (3-17 anys) que vulguin aprendre la tècnica de macramé, mitja i ganxet.', '1:30 h', '', 'Lloc: Locals Socials de Sant Daniel', '', '', 'Ass. Gent Gran de la Vall de Sant Daniel', TRUE, '', '', '{}', '', 'Extraescolar', '', '', '', '', 'girona')
